<script setup>
import { BriefcaseBusiness } from 'lucide-vue-next'
const props = defineProps({ slot: Object, busy: Boolean, now: Number, offset: Number, ranks: Array })
defineEmits(['action', 'mail'])
const deletedCopies = () => (props.slot.deletion_progress || []).filter(copy => copy.deleted).length
const money = value => new Intl.NumberFormat('en-US').format(value)
const cooled = job => job.available_at && Date.parse(job.available_at) > props.now + props.offset
const cooldown = job => Math.max(0, Math.ceil((Date.parse(job.available_at) - props.now - props.offset) / 1000))
</script>
<template>
            <div class="eyebrow">SERVICES / CONTRACT BROKER</div><div class="page-heading"><div><h1>Objectives. Nothing more<span>_</span></h1><p>Briefs disclose the target and desired result. Accept up to ten assignments. Briefings arrive in Email; reply there with evidence to collect payment.</p></div><span class="badge">{{ slot.rank_name.toUpperCase() }} ± 1</span></div>
            <div class="broker-policy"><span>LOCAL TERMINAL: <code>accept &lt;contract-id&gt;</code></span><span>SUCCESS: +REPUTATION / PAYMENT</span><span>DETECTION: −60 REP / AGENCY SETTLEMENT</span></div>
            <p v-if="slot.enforcement_cases?.length" class="message error">Agency cases are open. New reservations are suspended until bank payment and email confirmation. Existing assignments remain available.</p>
            <section class="panel broker-active"><span class="micro">ACCEPTED ASSIGNMENTS / {{ slot.accepted_contracts?.length || 0 }} OF 10</span><p v-if="!slot.accepted_contracts?.length" class="micro">No accepted assignments.</p><article v-for="job in slot.accepted_contracts || []" :key="job.id" class="assignment-row"><div><strong>{{ job.id }} / {{ job.title }}</strong><small>{{ job.target_name }}{{ job.focused ? ' · SELECTED' : '' }}</small></div><button class="button secondary" :disabled="busy || slot.connected || job.focused" @click="$emit('action', 'focus', job)">Select {{ job.id }}</button><button class="button secondary" :disabled="busy || (slot.connected && !job.focused)" @click="$emit('action', 'abort', job)">Abort · up to {{ 90 + job.rank * 80 }} CPH / −60 REP</button></article><button class="text-link" @click="$emit('mail')">Open Email for briefings and delivery</button><ul v-if="slot.deletion_progress?.length" class="deletion-checklist" aria-label="Required deletion copies"><li class="micro">SELECTED ASSIGNMENT · ERASE ALL COPIES · {{ deletedCopies() }}/{{ slot.deletion_progress.length }} RECEIPTS</li><li v-for="copy in slot.deletion_progress" :key="copy.path" :class="{ done: copy.deleted }">{{ copy.deleted ? '✓' : '○' }} {{ copy.path }}</li></ul></section>
            <p v-if="slot.broker_next_at" class="info-banner">Sourcing fresh assignments · next delivery in {{ Math.max(0, Math.ceil((Date.parse(slot.broker_next_at) - now - offset) / 1000)) }}s. Accepted assignments never return.</p>
            <p v-if="!slot.contracts.length" class="empty-state">No offers currently available. The broker is sourcing new contracts.</p>
            <div class="contract-grid"><article class="panel contract-card" v-for="job in slot.contracts" :key="job.id" :data-contract="job.id"><div class="contract-card-top"><span class="micro">CONTRACT {{ job.id }}</span><span class="badge">{{ slot.active_contract?.id === job.id ? 'RESERVED' : cooled(job) ? `SOURCING / ${cooldown(job)}s` : ranks[job.rank] }}</span></div><BriefcaseBusiness :size="25" class="contract-glyph" /><h2>{{ job.title }}</h2><span class="micro">{{ job.client.toUpperCase() }}</span><p>{{ job.description }}</p><dl class="job-details"><div><dt>CONTRACT ID</dt><dd class="contract-id">{{ job.id }}</dd></div><div><dt>TARGET</dt><dd>{{ job.target_name || job.target }}</dd></div><div><dt>ADDRESS</dt><dd>Look up this system in Atlas</dd></div><div><dt>SERVICE</dt><dd>{{ job.service_name }} · {{ job.port }}</dd></div><div><dt>ACCESS</dt><dd>Lockpick / optional exploit</dd></div><div><dt>ARTIFACT</dt><dd>{{ job.file }}</dd></div><div><dt>OBJECTIVE</dt><dd>{{ job.delete_paths?.length ? 'ERASE ALL COPIES' : job.objective.toUpperCase() }}</dd></div><div><dt>SECURITY</dt><dd>CLASS {{ job.security }}</dd></div><div><dt>FAILURE LIABILITY</dt><dd>UP TO {{ 90 + job.rank * 80 }} CPH</dd></div></dl><div class="contract-card-bottom"><strong class="reward">{{ money(job.reward) }} <small>CPH</small></strong><span class="micro">+{{ job.reputation }} REPUTATION</span></div><button v-if="slot.active_contract?.id === job.id" class="button secondary" :disabled="busy" @click="$emit('action', 'abort', job)">Abort · up to {{ 90 + job.rank * 80 }} CPH / −60 REP</button><button v-else class="button primary" :disabled="busy || (slot.accepted_contracts?.length || 0) >= 10 || !!slot.enforcement_cases?.length || cooled(job)" @click="$emit('action', 'accept', job)">Accept contract {{ job.id }}</button></article></div>
</template>
